% Inversion using high-resolution synthetic data (Section 6.5.3, Figs. 6.10-6.11 in the paper).
% Requires mat/fractal_fault_m1001_mp1001/receiverData.mat, generated by fractal_fault_generate_data.m.
addSubpaths;
maxIter = 200; % max number of optimization iterations
% Grid points in x-direction. Can be set before running the script, e.g. m=76
if ~exist('m', 'var')
    m = 251;
end
scalingStudy = false;
misfitType = 'velocity';
loadData = true; % Use high-resolution data instead of an inverse crime
% Data from another grid than m = m_p = 1001, e.g. data_m=251 (see fractal_fault_generate_data.m)
if exist('data_m', 'var')
    loadData = sprintf('mat/fractal_fault_m%d_mp%d/receiverData.mat', data_m, data_m);
end
% 'a' (Fig. 6.10) or 'tau0' (Fig. 6.11). Can be set before running the script, e.g.
% matlab -batch "inv_par='tau0'; high_res_data_inversion"
if ~exist('inv_par', 'var')
    inv_par = 'a';
end
switch inv_par
    case 'a'
        m_p = 26; % Grid points on parameter grid
        val = 0.0135; % initial value
        receiverSpacing = 2; % N_rec = 88
    case 'tau0'
        m_p = 51;
        val = 68;
        receiverSpacing = 1; % N_rec = 325
end
% Parameter grid size can be set before running the script, e.g. m_p_in=51
if exist('m_p_in', 'var')
    m_p = m_p_in;
end
optPars = {inv_par}; % parameter to invert for
% lbfgs, newton-tr, CG, newton-tr-noprec, fminunc-tr, newton-cg-ls (see adjopt.optimize_general).
if ~exist('opt_routine_str', 'var')
    opt_routine_str = 'lbfgs';
end
% To continue a stopped run, set loadOptPath to its mat/inversion/..._checkpoint.mat file
if ~exist('loadOptPath', 'var')
    loadOptPath = '';
end
% Regularization: 'none', 'tikhonov', 'tikhonov-grad', 'tv' or 'lasso' (see adjopt.regularization),
% with weight reg_beta. reg_eps smooths the absolute value in 'tv' and 'lasso'. E.g.
% matlab -batch "reg_type='tv'; reg_beta=1; high_res_data_inversion"
if ~exist('reg_type', 'var')
    reg_type = 'none';
end
if ~exist('reg_beta', 'var')
    reg_beta = 0;
end
regOpts = struct('type', reg_type, 'beta', reg_beta);
if exist('reg_eps', 'var')
    regOpts.eps = reg_eps;
end
% Hybrid: start from iteration x0_iter of the lbfgs run with the same settings, e.g.
% matlab -batch "opt_routine_str='newton-cg-ls'; x0_iter=40; reg_type='tv'; reg_beta=10; high_res_data_inversion"
if ~exist('x0_iter', 'var')
    x0_iter = [];
end
fprintf('RUNNING: %s, inverting for %s, regularization %s with beta = %g\n', opt_routine_str, inv_par, reg_type, reg_beta);
[parsVec, misFit, flag, output, history, initialPars, truePars, parSet] = optimize_antiplaneshear(maxIter, m, m_p, misfitType, optPars, val, scalingStudy, loadData, [], loadOptPath, opt_routine_str, receiverSpacing, regOpts, x0_iter);
